  "Justification for using default values": "기본값 사용의 정당성 근거",
  "Evidence of the carbon price due or paid in the country of origin":
    "원산지 국가에서 부과 또는 납부된 탄소 가격의 증빙",
  "The file was too large to keep in the browser, so there is nothing to read.":
    "파일이 너무 커서 브라우저에 보관할 수 없으므로 읽을 내용이 없습니다.",
  "Enter the values by hand.": "값을 직접 입력하세요.",
  "Nothing readable came back from the document.":
    "문서에서 읽을 수 있는 내용이 없습니다.",
  "Enter the values by hand — the file is still attached.":
    "값을 직접 입력하세요 — 파일은 여전히 첨부되어 있습니다.",
  "Extraction failed: {message}.": "추출 실패: {message}.",
  "The file is still attached — enter the values by hand.":
    "파일은 여전히 첨부되어 있습니다 — 값을 직접 입력하세요.",
  "{GB} kWh converted to {GB} MWh.": "{GB} kWh를 {GB} MWh로 변환했습니다.",
  "{GB} MWh written to this month.": "{GB} MWh를 이번 달에 기록했습니다.",
  "Recorded against the document.": "문서에 대해 기록되었습니다.",
  "This field is context for the verifier, not a calculation input.":
    "이 필드는 검증자를 위한 참고 정보이며 계산 입력값이 아닙니다.",
  "No extraction run": "추출이 실행되지 않음",
  "Extraction failed — enter values by hand":
    "추출 실패 — 값을 직접 입력하세요",
  "{accepted} of {length} proposed values accepted":
    "제안된 값 {length}개 중 {accepted}개 수락됨",
  "Coking coal / metallurgical coal": "코크스용 석탄 / 야금용 석탄",
  Coke: "코크스",
  "Anthracite / bituminous coal": "무연탄 / 역청탄",
  "Fuel oil / heavy fuel oil": "연료유 / 중유",
  "Coke oven gas": "코크스로 가스",
  "Blast furnace gas": "고로 가스",
  "Biomass / biofuel": "바이오매스 / 바이오연료",
  Anthracite: "무연탄",
  "Bituminous coal": "역청탄",
  "Sub-bituminous coal": "아역청탄",
  "Lignite / brown coal": "갈탄",
