  "Edit buyer": "구매자 편집",
  "Save buyer": "구매자 저장",
  "Shaded months are not readings.": "음영 처리된 월은 측정값이 아닙니다.",
  "They carry the year-to-date rate forward.":
    "연초부터 누적된 비율을 이어서 적용합니다.",
  "Part of a year, so not official.": "연간 일부이므로 공식 수치가 아닙니다.",
  "{counted} of {possible} months submitted.":
    "제출된 월 {counted}개 / 가능한 월 {possible}개.",
  "Explained by a gap entry": "누락 항목 기록으로 설명됨",
  "No reading and no explanation": "측정값과 설명 모두 없음",
  "Primary data": "1차 데이터",
  "After that, changing an input creates a new version with a reason rather than silently moving a signed number.":
    "이후 입력을 변경하면 서명된 수치를 몰래 바꾸는 대신, 사유가 포함된 새 버전이 만들어집니다.",
  "Calculation not frozen": "계산이 고정되지 않음",
  "Enter activity data first — a snapshot with no inputs proves nothing.":
    "먼저 활동 데이터를 입력하세요. 입력이 없는 스냅샷은 아무것도 증명하지 못합니다.",
  "Freeze calculation": "계산 고정",
  "Freezing captures the activity dataset, the precursor tree, the engine version and every output under one hash.":
    "고정하면 활동 데이터셋, 전구물질 트리, 엔진 버전 및 모든 출력이 하나의 해시로 기록됩니다.",
  "Inputs are now read-only.": "이제 입력값은 읽기 전용입니다.",
  "Not frozen": "고정되지 않음",
  "Nothing to freeze": "고정할 항목이 없습니다",
  "Outputs bind to this snapshot, so what was approved is what gets filed.":
    "출력은 이 스냅샷에 연결되므로, 승인된 내용이 그대로 제출됩니다.",
  "The calculation could not be frozen.": "계산을 고정할 수 없습니다.",
  "Buyer totals now include them.": "구매자 합계에 이제 이 항목이 포함됩니다.",
  "It returns to the not-yet-attributable list.":
    "아직 배분할 수 없는 항목 목록으로 돌아갑니다.",
  "Shipment unlinked": "출하 연결 해제됨",
  "A reason is required": "사유를 입력해야 합니다",
  "A verifier opening this dossier can answer every assertion without asking you a question.":
    "이 문서를 여는 검증기관은 질문을 하지 않고도 모든 진술에 답할 수 있습니다.",
  "All sixteen checks pass.": "16개 점검 항목을 모두 통과했습니다.",
  "An accepted warning travels into the dossier with its justification — that is what makes it defensible.":
    "승인된 경고는 그 정당성과 함께 문서에 포함됩니다. 이것이 근거를 방어 가능하게 만듭니다.",
  "Each one links to the screen that fixes it.":
    "각 항목은 이를 수정하는 화면으로 연결됩니다.",
  "Nothing blocks a filing.": "제출을 막는 항목은 없습니다.",
  "Recorded with your reason and included in the verification dossier.":
    "사유와 함께 기록되며 검증 문서에 포함됩니다.",
  "Add a process…": "공정 추가…",
  "Anything the list above does not name.": "위 목록에 없는 모든 항목입니다.",
  "Describe it in the field that appears.": "나타나는 필드에 설명하세요.",
  "Describe it in the terms your invoices use":
    "송장에서 사용하는 용어로 설명하세요",
  "Name it as your team names it": "팀에서 부르는 이름으로 적으세요",
  "Other — name it yourself": "기타 — 직접 이름 입력",
  "Other — specify": "기타 — 직접 입력",
  "You type the name and it joins the sequence.":
    "이름을 입력하면 순서 목록에 추가됩니다.",
  "Precursor deadline": "전구물질 마감일",
