    "기록됨 — 수출업체가 신규 설비인지 확인합니다.",
  "{depth} tiers upstream of you": "귀사 상류 {depth}단계",
  "Not eligible for actual value — see the data-origin note below":
    "실제 값 적용 대상이 아님 — 아래 데이터 출처 메모를 참조하세요",
  "Passed the four-check verification gate": "4단계 검증 게이트 통과",
