    "0으로 강제됨 — 스크랩에는 내재 배출량이 없습니다.",
  "From the CBAM catalogue — locked to the CN code beside it.":
    "CBAM 카탈로그에서 가져옴 — 옆의 CN 코드에 고정됩니다.",
  "From the CBAM catalogue — locked to the product beside it.":
    "CBAM 카탈로그에서 가져옴 — 옆의 제품에 고정됩니다.",
  "From this supplier's own CBAM communication.":
    "이 공급업체의 CBAM 커뮤니케이션에서 가져옴.",
  'It cannot be edited while the origin is "default value".':
    '출처가 "기본값"인 동안에는 편집할 수 없습니다.',
  "Pick a CN code and the product name fills in.":
    "CN 코드를 선택하면 제품명이 자동으로 입력됩니다.",
  "Pick the product from the catalogue above, or ask the supplier for actual data.":
    "위 카탈로그에서 제품을 선택하거나 공급업체에 실제 데이터를 요청하세요.",
  "Search the catalogue, or type it if it is not listed.":
    "카탈로그에서 검색하거나 목록에 없으면 직접 입력하세요.",
  "Send link": "링크 보내기",
  "An actual value, verified at the precursor's installation, may be lower.":
    "전구물질 설비에서 검증된 실제 값은 더 낮을 수 있습니다.",
  "Received — not usable yet": "수신됨 — 아직 사용할 수 없음",
  "Relying on a default for a direct precursor therefore tends to raise the overall figure for this product, and it can end up close to — or even above — the default value for the finished good itself.":
    "따라서 직접 전구물질에 기본값을 사용하면 이 제품의 전체 수치가 높아지는 경향이 있으며, 완제품 자체의 기본값에 가깝거나 그보다 높아질 수도 있습니다.",
  "Bound — counted": "연결됨 — 집계됨",
