  "Nothing was written.": "아무것도 기록되지 않았습니다.",
  "The coverage gap stays open.": "적용 범위의 공백은 여전히 열려 있습니다.",
  "The index entry was saved without the bytes.":
    "색인 항목은 바이트 데이터 없이 저장되었습니다.",
  "This is why a backend is the next step.":
    "이 때문에 다음 단계로 백엔드가 필요합니다.",
  "A process the list above does not name.": "위 목록에 없는 공정입니다.",
  "Other — describe it": "기타 — 설명 입력",
  "You type the name, and it stays available for further exclusions.":
    "이름을 입력하면 이후 제외 항목에서도 계속 사용할 수 있습니다.",
  "Everything already sent about this plant is filed under it, so it cannot be changed from here — if it names the wrong plant, stop and tell the exporter rather than answering for the wrong site.":
    "이 공장에 대해 이미 보낸 내용은 모두 이 공장 아래에 보관되어 있으므로 여기서 변경할 수 없습니다. 잘못된 공장을 지정했다면 잘못된 현장에 대해 답하지 말고 작업을 중단한 뒤 수출업체에 알리세요.",
  "Installation saved": "설비가 저장되었습니다",
  "Save installation": "설비 저장",
