  "· enter your output in Production to get the per-tonne figure":
    "· 톤당 수치를 얻으려면 생산 항목에 산출량을 입력하세요",
  "Your carbon data": "귀하의 탄소 자료",
  "Take me to the field": "해당 필드로 이동",
  "They’re outlined below with a note on what to check. Fix them and re-run the check before you sign.":
    "아래에 확인할 내용과 함께 윤곽선으로 표시되어 있습니다. 서명하기 전에 수정하고 점검을 다시 실행하세요.",
  "Jump to first flagged field": "표시된 첫 필드로 이동",
  "Back to overview": "개요로 돌아가기",
  "Continue to documents": "문서로 계속",
  "Certrace Supplier Portal": "Certrace 공급업체 포털",
  "What you’ll be asked for": "요청되는 항목",
  "Supporting documents": "증빙 문서",
  "Company & installation profile": "회사 및 설비 프로필",
  "Optional, and reusable. We save this securely so your installation identity pre-fills the questionnaire now and skips re-typing on every future request from any buyer.":
    "선택 사항이며 재사용됩니다. 설비 정보를 안전하게 저장하여 이번 설문에 미리 입력되고, 이후 모든 구매자의 요청에서 다시 입력할 필요가 없도록 합니다.",
  "Legal company name": "법인명",
  "Production installation": "생산 설비",
