  "Main production route": "주요 생산 경로",
  "e.g. EAF, BF-BOF, DRI-EAF.": "예: EAF, BF-BOF, DRI-EAF.",
  "EAF (electric arc furnace)": "EAF (전기 아크로)",
  "Skip for now": "지금은 건너뛰기",
  "Save & continue": "저장 후 계속",
