  "Your free trial ends tomorrow": "무료 체험이 내일 종료됩니다",
  "Your free trial ends in {n} days": "무료 체험이 {n}일 후 종료됩니다",
  "When the trial ends the account becomes read-only: you can still open everything, but nothing can be changed, sent or downloaded.":
    "체험이 종료되면 계정은 읽기 전용이 됩니다. 모든 항목을 계속 열 수 있지만 변경, 발송 또는 다운로드할 수 없습니다.",
  "Choose a plan before then to keep working without a break.":
    "중단 없이 계속 작업하려면 그 전에 요금제를 선택하세요.",
