  "Your other sessions were signed out": "다른 세션이 로그아웃되었습니다",
  "Every other browser and device signed in to your account was signed out.":
    "계정에 로그인되어 있던 다른 모든 브라우저와 기기가 로그아웃되었습니다.",
  "Only this one is signed in now.": "현재는 이 기기만 로그인되어 있습니다.",
  "Open security settings": "보안 설정 열기",
  "Ask Cera about this": "이 내용을 Cera에게 문의",
